//
//  AgentPatchApplier.swift
//  WillDeep
//
//  Parses and applies conservative unified diffs generated by the Agent.
//

import Foundation

struct AgentPatchFileChange: Equatable {
    let path: String
    let hunks: [AgentPatchHunk]
    /// True for a creation diff (`--- /dev/null` / `new file mode`). The
    /// target file is expected NOT to exist yet; applying it writes the
    /// hunk's added lines as the whole new file.
    var isNewFile: Bool = false
}

struct AgentPatchHunk: Equatable {
    let oldStart: Int
    let lines: [AgentPatchLine]
}

struct AgentPatchLine: Equatable {
    enum Kind: Equatable {
        case context
        case removed
        case added
    }

    let kind: Kind
    let text: String
}

enum AgentPatchApplier {
    static func extractDiffBlocks(from text: String) -> [String] {
        var blocks: [String] = []
        var current: [String] = []
        var isInFence = false
        var fenceLooksLikeDiff = false

        for line in text.components(separatedBy: .newlines) {
            if line.trimmingCharacters(in: .whitespaces).hasPrefix("```") {
                if isInFence {
                    if fenceLooksLikeDiff {
                        let diff = current.joined(separator: "\n").trimmingCharacters(in: .whitespacesAndNewlines)
                        if !diff.isEmpty {
                            blocks.append(diff)
                        }
                    }
                    current = []
                    isInFence = false
                    fenceLooksLikeDiff = false
                } else {
                    isInFence = true
                    let marker = line.lowercased()
                    fenceLooksLikeDiff = marker.contains("diff") || marker.contains("patch")
                }
                continue
            }

            if isInFence {
                current.append(line)
            }
        }

        if blocks.isEmpty, text.contains("@@") {
            blocks.append(text.trimmingCharacters(in: .whitespacesAndNewlines))
        }

        return blocks
    }

    static func parse(_ diff: String) throws -> [AgentPatchFileChange] {
        let trimmed = diff.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { throw AgentPatchError.emptyDiff }

        let lines = trimmed.components(separatedBy: .newlines)
        var changes: [AgentPatchFileChange] = []
        var currentPath: String?
        var currentHunks: [AgentPatchHunk] = []
        var currentHunkStart: Int?
        var currentHunkLines: [AgentPatchLine] = []
        var currentIsNewFile = false

        func flushHunk() {
            guard let start = currentHunkStart else { return }
            currentHunks.append(AgentPatchHunk(oldStart: start, lines: currentHunkLines))
            currentHunkStart = nil
            currentHunkLines = []
        }

        func flushFile() {
            flushHunk()
            guard let path = currentPath else { return }
            changes.append(AgentPatchFileChange(path: path, hunks: currentHunks, isNewFile: currentIsNewFile))
            currentPath = nil
            currentHunks = []
            currentIsNewFile = false
        }

        for rawLine in lines {
            if rawLine.hasPrefix("diff --git ") {
                flushFile()
                continue
            }

            // Git emits this right after `diff --git` for a creation; treat
            // it as a new-file hint even if the `--- /dev/null` line is
            // absent or reordered.
            if rawLine.hasPrefix("new file mode") {
                currentIsNewFile = true
                continue
            }

            if rawLine.hasPrefix("+++ ") {
                let path = String(rawLine.dropFirst(4)).trimmingCharacters(in: .whitespaces)
                // `+++ /dev/null` is a deletion — not supported yet.
                guard path != "/dev/null" else { throw AgentPatchError.unsupportedDiff }
                currentPath = normalizedPath(path)
                continue
            }

            if rawLine.hasPrefix("--- ") {
                let path = String(rawLine.dropFirst(4)).trimmingCharacters(in: .whitespaces)
                // `--- /dev/null` means the file is being CREATED (no old
                // version). Allow it and mark the change as a new file.
                if path == "/dev/null" {
                    currentIsNewFile = true
                }
                continue
            }

            if rawLine.hasPrefix("@@") {
                flushHunk()
                currentHunkStart = try oldStart(from: rawLine)
                continue
            }

            guard currentHunkStart != nil else { continue }

            if rawLine.hasPrefix("+") {
                currentHunkLines.append(AgentPatchLine(kind: .added, text: String(rawLine.dropFirst())))
            } else if rawLine.hasPrefix("-") {
                currentHunkLines.append(AgentPatchLine(kind: .removed, text: String(rawLine.dropFirst())))
            } else if rawLine.hasPrefix(" ") {
                currentHunkLines.append(AgentPatchLine(kind: .context, text: String(rawLine.dropFirst())))
            } else if rawLine.hasPrefix("\\ No newline at end of file") {
                continue
            } else {
                throw AgentPatchError.unsupportedDiff
            }
        }

        flushFile()

        guard !changes.isEmpty, changes.allSatisfy({ !$0.hunks.isEmpty }) else {
            throw AgentPatchError.unsupportedDiff
        }

        return changes
    }

    static func apply(_ change: AgentPatchFileChange, to content: String) throws -> String {
        // New file: there's no base content to match against — the whole
        // file is the hunks' added lines, in order.
        if change.isNewFile {
            let added = change.hunks.flatMap { hunk in
                hunk.lines.compactMap { $0.kind == .added ? $0.text : nil }
            }
            return added.joined(separator: "\n")
        }

        var lines = content.components(separatedBy: "\n")
        var searchOffset = 0

        for hunk in change.hunks {
            let expected = hunk.lines.compactMap { line -> String? in
                switch line.kind {
                case .context, .removed:
                    return line.text
                case .added:
                    return nil
                }
            }
            let replacement = hunk.lines.compactMap { line -> String? in
                switch line.kind {
                case .context, .added:
                    return line.text
                case .removed:
                    return nil
                }
            }

            let preferredIndex = max(0, hunk.oldStart - 1 + searchOffset)
            guard let index = matchingIndex(for: expected, in: lines, near: preferredIndex) else {
                throw AgentPatchError.hunkDidNotMatch(change.path)
            }

            lines.replaceSubrange(index..<(index + expected.count), with: replacement)
            searchOffset += replacement.count - expected.count
        }

        return lines.joined(separator: "\n")
    }

    private static func normalizedPath(_ path: String) -> String {
        var result = path
        if result.hasPrefix("a/") || result.hasPrefix("b/") {
            result = String(result.dropFirst(2))
        }
        return result.trimmingCharacters(in: CharacterSet(charactersIn: "\""))
    }

    private static func oldStart(from header: String) throws -> Int {
        guard let range = header.range(of: #"@@ -(\d+)(?:,\d+)? \+\d+(?:,\d+)? @@"#, options: .regularExpression) else {
            throw AgentPatchError.unsupportedDiff
        }

        let match = String(header[range])
        guard let numberRange = match.range(of: #"(?<=@@ -)\d+"#, options: .regularExpression),
              let start = Int(match[numberRange]) else {
            throw AgentPatchError.unsupportedDiff
        }
        return start
    }

    private static func matchingIndex(for expected: [String], in lines: [String], near preferredIndex: Int) -> Int? {
        guard !expected.isEmpty else {
            return min(preferredIndex, lines.count)
        }
        guard expected.count <= lines.count else { return nil }

        let nearbyRange = max(0, preferredIndex - 6)...min(lines.count - expected.count, preferredIndex + 6)
        for index in nearbyRange where matches(expected, in: lines, at: index) {
            return index
        }

        for index in 0...(lines.count - expected.count) where matches(expected, in: lines, at: index) {
            return index
        }

        return nil
    }

    private static func matches(_ expected: [String], in lines: [String], at index: Int) -> Bool {
        guard index >= 0, index + expected.count <= lines.count else { return false }
        for offset in expected.indices where lines[index + offset] != expected[offset] {
            return false
        }
        return true
    }
}
